import{ad as c,N as m,$ as _,Q as i,j as n,g as e,o as b,n as l,a4 as s,a9 as f,m as q,i as g,X as P}from"./chunks/framework.Ce_49mA8.js";const k={id:"лицензионное-соглашение-договор-оферта-и-политика-обработки-персональных-данных",tabindex:"-1"},x=["href"],D=JSON.parse('{"title":"Лицензионное соглашение и конфиденциальность","description":"Лицензионное соглашение (договор-оферта), Политика конфиденциальности и правила оплаты ОмниКрафт ЕРП.","frontmatter":{"title":"Лицензионное соглашение и конфиденциальность","description":"Лицензионное соглашение (договор-оферта), Политика конфиденциальности и правила оплаты ОмниКрафт ЕРП.","order":20,"eula_version":20261127,"eula_date":"2026-11-27","datePublished":"2026-11-14","dateModified":"2026-11-27"},"headers":[],"relativePath":"ru/docs/terms.md","filePath":"ru/docs/terms.md","lastUpdated":1795737600000}'),y={name:"ru/docs/terms.md"},T=Object.assign(y,{setup(v){const{frontmatter:h}=c(),r=P("");m(()=>{r.value="nm@omnicraft-erp.com"});const d=t=>{if(!t)return"";const[a,o,u]=t.split("-"),p=["января","февраля","марта","апреля","мая","июня","июля","августа","сентября","октября","ноября","декабря"];return`${parseInt(u)} ${p[parseInt(o)-1]} ${a} года`};return(t,a)=>{const o=_("DocIcon");return i(),n("div",null,[e("h1",k,[b(o,{name:"terms"}),a[0]||(a[0]=l(" Лицензионное соглашение (договор-оферта) и Политика обработки персональных данных ",-1)),a[1]||(a[1]=e("a",{class:"header-anchor",href:"#лицензионное-соглашение-договор-оферта-и-политика-обработки-персональных-данных","aria-label":'Permalink to "Лицензионное соглашение (договор-оферта) и Политика обработки персональных данных"'},"​",-1))]),e("p",null,[e("em",null,"Действующая редакция от "+s(d(f(h).eula_date)),1)]),a[6]||(a[6]=q('<p>Настоящий документ является официальным предложением (публичной офертой) и представляет собой единый договор-оферту между вами (далее — «Пользователь») и Разработчиком (далее — «Лицензиар») об использовании программы для ЭВМ «ОмниКрафт ЕРП» (далее — «Программа») и официального сайта.</p><p>Установка, копирование, загрузка, оплата или иное использование Программы означает безоговорочное согласие Пользователя со всеми условиями настоящего документа. Если вы не согласны с условиями, вы обязаны прекратить использование Программы и удалить её со своих устройств.</p><hr><h2 id="часть-1-лицензионныи-договор-оферта" tabindex="-1">ЧАСТЬ 1. ЛИЦЕНЗИОННЫЙ ДОГОВОР-ОФЕРТА <a class="header-anchor" href="#часть-1-лицензионныи-договор-оферта" aria-label="Permalink to &quot;ЧАСТЬ 1. ЛИЦЕНЗИОННЫЙ ДОГОВОР-ОФЕРТА&quot;">​</a></h2><h3 id="_1-1-предмет-соглашения-и-принцип-работы" tabindex="-1">1.1. Предмет соглашения и принцип работы <a class="header-anchor" href="#_1-1-предмет-соглашения-и-принцип-работы" aria-label="Permalink to &quot;1.1. Предмет соглашения и принцип работы&quot;">​</a></h3><p>Лицензиар предоставляет Пользователю персональное, неисключительное, непередаваемое право использования Программы в соответствии с её функциональным назначением на территории всего мира на весь срок действия исключительного права.</p><p>Программа разработана на базе архитектуры с приоритетом локального хранения данных. Обработка данных и ведение учёта осуществляются на вычислительных ресурсах Пользователя. Лицензиар не хранит базы данных Пользователя на своих серверах и не имеет к ним доступа. Вся учётная и коммерческая информация (базы данных, технологические карты, финансовые проводки, клиентская база, остатки товаров и материалов) создаётся, обрабатывается и хранится под исключительным контролем Пользователя — на его локальных накопителях либо в подключаемых Пользователем персональных хранилищах данных.</p><h3 id="_1-2-типы-лицензии-и-тарифы" tabindex="-1">1.2. Типы лицензий и тарифы <a class="header-anchor" href="#_1-2-типы-лицензии-и-тарифы" aria-label="Permalink to &quot;1.2. Типы лицензий и тарифы&quot;">​</a></h3><p>Лицензиар предоставляет права использования Программы в объёме функциональных возможностей, определяемых выбранным Пользователем тарифным планом (типом лицензии).</p><p>Полный перечень действующих тарифных планов, доступный функционал, сроки действия, правила ознакомительного доступа и стоимость лицензий зафиксированы в открытом доступе на официальной странице <a href="/ru/docs/buy-license">Приобретение лицензии</a> и в <a href="/ru/docs/licenses">Руководстве по лицензированию</a>, являющихся неотъемлемой частью настоящей Оферты.</p><p>Коммерческий лицензионный ключ технически привязывается к уникальному аппаратному отпечатку оборудования Пользователя и допускает одновременную активацию не более чем на 5 (пяти) устройствах Пользователя с возможностью самостоятельного сброса и переноса привязок в личном кабинете.</p><h3 id="_1-3-ограничения-использования" tabindex="-1">1.3. Ограничения использования <a class="header-anchor" href="#_1-3-ограничения-использования" aria-label="Permalink to &quot;1.3. Ограничения использования&quot;">​</a></h3><p>Пользователю запрещается:</p><ul><li>Декомпилировать, дизассемблировать, модифицировать или пытаться извлечь исходный код Программы.</li><li>Сдавать Программу в аренду, продавать, сублицензировать или передавать лицензионные ключи активации третьим лицам.</li><li>Использовать Программу для совершения действий, противоречащих действующему законодательству Российской Федерации.</li><li>Пытаться обойти технические ограничения ознакомительной версии любым способом.</li></ul><h3 id="_1-4-ограничение-ответственности-и-отказ-от-гарантии" tabindex="-1">1.4. Ограничение ответственности и отказ от гарантий <a class="header-anchor" href="#_1-4-ограничение-ответственности-и-отказ-от-гарантии" aria-label="Permalink to &quot;1.4. Ограничение ответственности и отказ от гарантий&quot;">​</a></h3><p><strong>Программа предоставляется на условиях «как есть». Лицензиар не предоставляет никаких явных или подразумеваемых гарантий того, что Программа будет отвечать требованиям Пользователя, будет работать непрерывно, без сбоев и ошибок.</strong></p><p><strong>Пользователь понимает и соглашается, что Лицензиар ни при каких обстоятельствах не несет ответственности за:</strong></p><ol><li>Утерю, искажение или повреждение локальных баз данных Пользователя в результате сбоев питания, поломки накопителей, действия вредоносных программ или некорректных действий Пользователя.</li><li>Любые прямые или косвенные убытки, упущенную выгоду или прерывание деловой активности, возникшие в результате использования или невозможности использования Программы.</li></ol><p><strong>Резервное копирование:</strong> Пользователь осознает, что вся ответственность за сохранность коммерческой информации лежит исключительно на нем. Пользователь обязуется самостоятельно и регулярно выполнять резервное копирование своих данных с использованием встроенных инструментов Программы на внешние носители или персональные хранилища.</p><p><strong>Интеграция с сервисами искусственного интеллекта и обработка данных:</strong> Программное обеспечение предоставляет функциональность взаимодействия со сторонними сервисами искусственного интеллекта по модели прямого подключения со своими ключами доступа, а также с автономными локальными моделями. Пользователь осознаёт и безоговорочно соглашается со следующим:</p><ol><li>При использовании внешних облачных моделей текст формируемых запросов и рабочий контекст (включая наименования материалов, параметры изделий, тексты описаний, примечания к заказам и сопутствующие данные) передаются напрямую с устройства Пользователя на сервера выбранного Пользователем стороннего сервиса с использованием персонального ключа доступа Пользователя. Лицензиар не имеет доступа к данным каналам связи, не перехватывает, не анализирует и не сохраняет содержимое запросов к искусственному интеллекту.</li><li>В случае внесения Пользователем в запросы к искусственному интеллекту персональных данных физических лиц (включая клиентов, заказчиков, контрагентов или сотрудников) либо сведений, составляющих охраняемую законом тайну, Пользователь выступает самостоятельным оператором таких данных и несёт полную единоличную ответственность за соблюдение применимого законодательства о персональных данных (включая Федеральный закон от 27.07.2006 № 152-ФЗ «О персональных данных», требования к трансграничной передаче и получение согласий субъектов). Лицензиар не несёт ответственности за действия сторонних сервисов искусственного интеллекта в отношении переданных Пользователем сведений.</li><li>Пользователь имеет техническую возможность полностью исключить передачу данных во внешние сети, выбрав использование локальных автономных моделей искусственного интеллекта, исполняемых исключительно на аппаратных ресурсах устройства Пользователя в офлайн-режиме без подключения к сети Интернет.</li><li>Все сведения, расчёты, генерации и материалы, сформированные с применением технологий искусственного интеллекта, предоставляются на условиях «как есть» и носят исключительно информационный и вспомогательный характер. Пользователь обязан самостоятельно проверять любые производственные, экономические и финансовые данные перед их утверждением и практическим применением.</li></ol><p><strong>Предел ответственности Лицензиара:</strong> Совокупная ответственность Лицензиара по любым требованиям, претензиям или искам, связанным с настоящим Соглашением или работой Программы, при любых обстоятельствах строго ограничена документально подтверждённым реальным ущербом и ни при каких условиях не может превышать сумму, фактически уплаченную Пользователем за соответствующую лицензию. В отношении бесплатной ознакомительной версии Программы Лицензиар не несёт никакой финансовой ответственности. Лицензиар ни при каких обстоятельствах не несёт ответственности за упущенную выгоду, косвенные убытки, простой деятельности или потерю данных Пользователя.</p><h3 id="_1-5-условия-оплаты-доставки-и-возврата-средств" tabindex="-1">1.5. Условия оплаты, доставки и возврата средств <a class="header-anchor" href="#_1-5-условия-оплаты-доставки-и-возврата-средств" aria-label="Permalink to &quot;1.5. Условия оплаты, доставки и возврата средств&quot;">​</a></h3><p>Порядок оплаты лицензионных ключей, способы доставки цифрового товара, а также правила, сроки и исчерпывающий регламент возврата денежных средств подробно зафиксированы в <a href="#payment-delivery-returns">Части 3 настоящего Соглашения</a>.</p><hr><h2 id="privacy-policy" tabindex="-1">ЧАСТЬ 2. ПОЛИТИКА ОБРАБОТКИ ПЕРСОНАЛЬНЫХ ДАННЫХ (ПОЛИТИКА КОНФИДЕНЦИАЛЬНОСТИ) <a class="header-anchor" href="#privacy-policy" aria-label="Permalink to &quot;ЧАСТЬ 2. ПОЛИТИКА ОБРАБОТКИ ПЕРСОНАЛЬНЫХ ДАННЫХ (ПОЛИТИКА КОНФИДЕНЦИАЛЬНОСТИ) {#privacy-policy}&quot;">​</a></h2><h3 id="_2-1-отсутствие-сбора-данных-локальных-проектов" tabindex="-1">2.1. Отсутствие сбора данных локальных проектов <a class="header-anchor" href="#_2-1-отсутствие-сбора-данных-локальных-проектов" aria-label="Permalink to &quot;2.1. Отсутствие сбора данных локальных проектов&quot;">​</a></h3><p>В связи с архитектурой приоритета локального хранения данных Лицензиар не имеет доступа к базам данных Пользователя. Лицензиар не собирает, не обрабатывает и не хранит персональные данные клиентов Пользователя, списки поставщиков, коммерческую тайну, информацию о доходах, остатках на счетах и иную пользовательскую информацию.</p><p>Лицензиар не является оператором персональных данных (в терминологии Федерального закона № 152-ФЗ «О персональных данных») применительно к информации, вносимой Пользователем в базу данных Программы.</p><h3 id="_2-2-автоматически-собираемая-техническая-информация-телеметрия" tabindex="-1">2.2. Автоматически собираемая техническая информация (Телеметрия) <a class="header-anchor" href="#_2-2-автоматически-собираемая-техническая-информация-телеметрия" aria-label="Permalink to &quot;2.2. Автоматически собираемая техническая информация (Телеметрия)&quot;">​</a></h3><p>Для обеспечения работы системы лицензирования и улучшения качества Программы, Лицензиар может собирать исключительно обезличенную техническую информацию:</p><ul><li><strong>Уникальный аппаратный код оборудования:</strong> Обезличенный криптографический хэш параметров оборудования. Он используется исключительно для проверки привязки лицензионного ключа и защиты от несанкционированного копирования. Данный код не позволяет идентифицировать конкретное физическое лицо.</li><li><strong>Технические метрики:</strong> Язык интерфейса, версия операционной системы, версия Программы и счетчик проведённых операций (для контроля лимита бесплатной ознакомительной версии).</li><li><strong>Отчеты о сбоях:</strong> В случае критической ошибки Программа формирует технический отчет о последовательности вызовов (трассировку стека). Программа автоматически вырезает персональные пути локальных папок компьютера, заменяя их на обезличенные маски, чтобы исключить передачу имени учетной записи операционной системы.</li></ul><h3 id="_2-3-обработка-данных-при-оформлении-платежа" tabindex="-1">2.3. Обработка данных при оформлении платежа <a class="header-anchor" href="#_2-3-обработка-данных-при-оформлении-платежа" aria-label="Permalink to &quot;2.3. Обработка данных при оформлении платежа&quot;">​</a></h3><ul><li>При оформлении и оплате лицензии через авторизованный платёжный сервис Пользователь указывает адрес электронной почты и аппаратный код устройства.</li><li>Предоставляя данные, Пользователь выражает свое согласие на обработку этой информации Лицензиаром исключительно в целях автоматической генерации, доставки и технического сопровождения лицензионного ключа.</li><li><strong>В целях обеспечения конфиденциальности и минимизации собираемых сведений, адрес электронной почты используется исключительно для отправки сообщения с лицензионным ключом непосредственно в момент совершения транзакции и не сохраняется в постоянных базах данных на серверах Лицензиара.</strong> В базе данных лицензий сохраняются только обезличенный лицензионный ключ и зашифрованный отпечаток устройства.</li><li>Оформление заказа и транзитная обработка адреса электронной почты для отправки ключа осуществляются на серверах, расположенных на территории Российской Федерации. При оформлении заказа из-за пределов Российской Федерации Пользователь выражает явное согласие на обработку указанного адреса электронной почты на серверах в Российской Федерации исключительно в целях исполнения договора и доставки цифрового лицензионного ключа.</li><li>Обработка данных осуществляется с соблюдением требований законодательства Российской Федерации. Данные не передаются третьим лицам (за исключением законных требований уполномоченных государственных органов РФ).</li></ul><h3 id="_2-4-управление-согласием-отказ-от-сбора" tabindex="-1">2.4. Управление согласием (Отказ от сбора) <a class="header-anchor" href="#_2-4-управление-согласием-отказ-от-сбора" aria-label="Permalink to &quot;2.4. Управление согласием (Отказ от сбора)&quot;">​</a></h3><p>Пользователь имеет право в любой момент отозвать свое согласие на передачу аналитической информации и отчетов об ошибках. Для этого достаточно снять соответствующую отметку в разделе <a href="./global-settings">Глобальные настройки</a>. При отключении данного параметра Программа переходит в полностью автономный режим (за исключением разовых обращений к серверу при активации коммерческого лицензионного ключа).</p><h3 id="_2-5-использование-веб-ресурсов" tabindex="-1">2.5. Использование веб-ресурсов <a class="header-anchor" href="#_2-5-использование-веб-ресурсов" aria-label="Permalink to &quot;2.5. Использование веб-ресурсов&quot;">​</a></h3><p>При посещении официального сайта <code>omnicraft-erp.com</code> или обращении к официальным серверам авторизации Лицензиара веб-сервер может автоматически фиксировать стандартные технические журналы подключений (сетевой адрес устройства, тип браузера, время доступа) исключительно в целях обеспечения сетевой безопасности и защиты от распределённых атак. Сайт не использует рекламные или отслеживающие сторонние файлы «куки».</p><h3 id="_2-6-использование-сессионного-хранилища-браузера" tabindex="-1">2.6. Использование сессионного хранилища браузера <a class="header-anchor" href="#_2-6-использование-сессионного-хранилища-браузера" aria-label="Permalink to &quot;2.6. Использование сессионного хранилища браузера&quot;">​</a></h3><p>Сайт использует сессионное хранилище браузера исключительно для поддержания технической работоспособности личного кабинета и сохранения статуса авторизации в рамках активной сессии пользователя. Хранение данных осуществляется локально на устройстве пользователя. Внесённые сведения не используются для отслеживания или рекламы и автоматически стираются браузером при закрытии вкладки или окна.</p><hr><h2 id="payment-delivery-returns" tabindex="-1">ЧАСТЬ 3. ПРАВИЛА ОПЛАТЫ, ДОСТАВКИ И ВОЗВРАТА СРЕДСТВ <a class="header-anchor" href="#payment-delivery-returns" aria-label="Permalink to &quot;ЧАСТЬ 3. ПРАВИЛА ОПЛАТЫ, ДОСТАВКИ И ВОЗВРАТА СРЕДСТВ {#payment-delivery-returns}&quot;">​</a></h2><h3 id="_3-1-описание-цифрового-товара-и-потребительские-своиства" tabindex="-1">3.1. Описание цифрового товара и потребительские свойства <a class="header-anchor" href="#_3-1-описание-цифрового-товара-и-потребительские-своиства" aria-label="Permalink to &quot;3.1. Описание цифрового товара и потребительские свойства&quot;">​</a></h3><p>Товаром является неисключительное право использования программы для ЭВМ (цифровой лицензионный ключ активации).</p><p>Потребительские свойства: активация лицензионного ключа в программе ОмниКрафт ЕРП снимает базовое техническое ограничение бесплатной ознакомительной версии и, в соответствии с выбранным тарифным планом, предоставляет доступ к расширенным функциональным возможностям. Товар поставляется исключительно в цифровом (электронном) виде.</p><h3 id="_3-2-способы-и-условия-оплаты" tabindex="-1">3.2. Способы и условия оплаты <a class="header-anchor" href="#_3-2-способы-и-условия-оплаты" aria-label="Permalink to &quot;3.2. Способы и условия оплаты&quot;">​</a></h3><p>Оплата лицензии производится в безналичном порядке онлайн через авторизованный платёжный сервис (интернет-эквайринг), соответствующий государственным и международным стандартам безопасности данных индустрии платёжных карт.</p><p>Все платёжные реквизиты передаются по защищённому криптографическому протоколу шифрования данных.</p><p>Актуальный перечень доступных способов оплаты (банковские карты платёжных систем, система быстрых платежей и иные электронные методы) определяется платёжным сервисом на момент совершения транзакции и отображается непосредственно в платёжной форме при оформлении заказа на странице <a href="/ru/docs/buy-license">Приобретение лицензии</a>.</p><h3 id="_3-3-порядок-и-сроки-доставки-цифрового-ключа" tabindex="-1">3.3. Порядок и сроки доставки цифрового ключа <a class="header-anchor" href="#_3-3-порядок-и-сроки-доставки-цифрового-ключа" aria-label="Permalink to &quot;3.3. Порядок и сроки доставки цифрового ключа&quot;">​</a></h3><ul><li>Доставка цифрового товара осуществляется путём отправки электронного письма с лицензионным ключом на адрес электронной почты, указанный Покупателем при оплате.</li><li>Срок доставки: электронное письмо с лицензионным ключом направляется в автоматическом режиме незамедлительно после подтверждения оплаты платёжным сервисом, но не позднее 24 часов с момента совершения платежа.</li></ul><h3 id="_3-4-исчерпывающии-регламент-возврата-денежных-средств" tabindex="-1">3.4. Исчерпывающий регламент возврата денежных средств <a class="header-anchor" href="#_3-4-исчерпывающии-регламент-возврата-денежных-средств" aria-label="Permalink to &quot;3.4. Исчерпывающий регламент возврата денежных средств&quot;">​</a></h3><ul><li><p><strong>Отказ до момента получения цифрового товара:</strong><br> Покупатель имеет право отказаться от покупки и вернуть уплаченные средства в любой момент до фактической автоматической генерации и отправки лицензионного ключа на электронную почту.</p></li><li><p><strong>Пошаговый регламент действий для возврата средств:</strong></p><ol><li>Для оформления возврата Пользователь направляет заявление в свободной форме через страницу <a href="/ru/docs/contacts">Контакты и реквизиты</a>. В обращении необходимо указать дату платежа, сумму и адрес электронной почты, указанный при оформлении заказа.</li><li>Заявление о возврате рассматривается Лицензиаром, и возврат денежных средств осуществляется в срок <strong>до 10 (десяти) календарных дней</strong> со дня получения обращения в соответствии со статьями 22 и 26.1 Закона РФ «О защите прав потребителей».</li><li>После подтверждения возврат денежных средств осуществляется в полном объёме (<strong>100% уплаченной суммы без удержания комиссий</strong>) на тот же счёт или банковскую карту, с которой производилась оплата.</li><li>Фактический срок зачисления денежных средств на счёт Пользователя определяется регламентом его банка-эмитента и правилами платёжных систем (как правило, до 30 календарных дней).</li></ol></li><li><p><strong>Отказ после получения цифрового товара:</strong><br> Предоставление Пользователю неисключительного права на Программу считается полностью состоявшимся (услуга оказана в полном объёме) в момент автоматической генерации и отправки Пользователю уникального лицензионного ключа активации на его адрес электронной почты. В соответствии со статьёй 1235 Гражданского кодекса РФ, статьёй 26.1 Закона РФ «О защите прав потребителей» и Постановлением Правительства РФ № 2463, возврат денежных средств за цифровой продукт надлежащего качества после его передачи Пользователю не производится.</p><p>Перед приобретением коммерческой лицензии Пользователю предоставляется бесплатная ознакомительная версия Программы без ограничения по времени для полной оценки её характеристик, совместимости и потребительских свойств. В случае возникновения любых технических проблем с активацией ключа Лицензиар обязуется оперативно устранить проблему или произвести замену ключа.</p></li></ul><hr><h2 id="часть-4-заключительные-положения-и-реквизиты" tabindex="-1">ЧАСТЬ 4. ЗАКЛЮЧИТЕЛЬНЫЕ ПОЛОЖЕНИЯ И РЕКВИЗИТЫ <a class="header-anchor" href="#часть-4-заключительные-положения-и-реквизиты" aria-label="Permalink to &quot;ЧАСТЬ 4. ЗАКЛЮЧИТЕЛЬНЫЕ ПОЛОЖЕНИЯ И РЕКВИЗИТЫ&quot;">​</a></h2><h3 id="_4-1-применимое-право-и-разрешение-споров" tabindex="-1">4.1. Применимое право и разрешение споров <a class="header-anchor" href="#_4-1-применимое-право-и-разрешение-споров" aria-label="Permalink to &quot;4.1. Применимое право и разрешение споров&quot;">​</a></h3><p>Настоящее Соглашение регулируется и толкуется в соответствии с действующим законодательством Российской Федерации. Все споры и разногласия подлежат обязательному досудебному претензионному урегулированию. Срок рассмотрения письменной претензии составляет 30 (тридцать) календарных дней с момента её получения. При невозможности урегулирования спора в досудебном порядке, он подлежит рассмотрению в суде по месту нахождения Лицензиара.</p><h3 id="_4-2-обстоятельства-непреодолимои-силы-форс-мажор" tabindex="-1">4.2. Обстоятельства непреодолимой силы (Форс-мажор) <a class="header-anchor" href="#_4-2-обстоятельства-непреодолимои-силы-форс-мажор" aria-label="Permalink to &quot;4.2. Обстоятельства непреодолимой силы (Форс-мажор)&quot;">​</a></h3><p>Стороны освобождаются от ответственности за частичное или полное неисполнение обязательств по настоящему Соглашению, если оно явилось следствием обстоятельств непреодолимой силы. К таким обстоятельствам относятся чрезвычайные и непредотвратимые события, включая военные действия, стихийные бедствия, решения государственных органов, масштабные аварии в работе сети Интернет, сбои серверов или облачных провайдеров, а также тяжелая внезапная болезнь либо экстренная госпитализация Лицензиара, объективно препятствующая исполнению обязательств в установленный срок.</p><h3 id="_4-3-изменение-условии" tabindex="-1">4.3. Изменение условий <a class="header-anchor" href="#_4-3-изменение-условии" aria-label="Permalink to &quot;4.3. Изменение условий&quot;">​</a></h3><p>Лицензиар оставляет за собой право в одностороннем порядке вносить изменения в настоящее Соглашение. Новая редакция вступает в силу с момента её публикации на официальном сайте Программы. В случае несогласия Пользователя с изменениями Соглашения, Пользователь обязан прекратить использование Программы и удалить её со своих устройств.</p><h3 id="_4-4-превалирование-языка" tabindex="-1">4.4. Превалирование языка <a class="header-anchor" href="#_4-4-превалирование-языка" aria-label="Permalink to &quot;4.4. Превалирование языка&quot;">​</a></h3><p>Настоящее Соглашение может быть переведено на другие языки для удобства Пользователей. В случае любых разночтений, расхождений или противоречий между версией Соглашения на русском языке и версией на любом другом языке, преимущественную (превалирующую) и окончательную юридическую силу всегда имеет версия на русском языке.</p><h3 id="_4-5-реквизиты-разработчика-лицензиара" tabindex="-1">4.5. Реквизиты Разработчика (Лицензиара) <a class="header-anchor" href="#_4-5-реквизиты-разработчика-лицензиара" aria-label="Permalink to &quot;4.5. Реквизиты Разработчика (Лицензиара)&quot;">​</a></h3><p>Правообладателем и Разработчиком Программы является: <strong>Физическое лицо Мурашкин Николай Валерьевич</strong>, применяющее специальный налоговый режим «Налог на профессиональный доход» (самозанятый). Подробная информация о разработчике доступна в разделе <a href="/ru/docs/about">О разработчиках</a>.</p>',65)),e("ul",null,[a[5]||(a[5]=e("li",null,[e("strong",null,"ИНН:"),l(" 232904256501")],-1)),e("li",null,[a[2]||(a[2]=e("strong",null,"Официальный адрес электронной почты:",-1)),a[3]||(a[3]=l()),r.value?(i(),n("a",{key:0,href:"mailto:"+r.value,class:"eula-email"},s(r.value),9,x)):g("",!0),a[4]||(a[4]=l(" (для направления юридически значимых сообщений, уведомлений и досудебных претензий)",-1))])])])}}});export{D as __pageData,T as default};
